def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n.

    The input must be a perfect square. The result is a plain int.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("input must be an int, got %r" % type(n).__name__)
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Integer Newton iteration (Heron's method), converges in a handful of
    # steps for any size of input, with no float-rounding errors.
    x = 1 << ((n.bit_length() + 1) // 2)  # initial guess: >= sqrt(n)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    if x * x != n:
        raise ValueError("%d is not a perfect square" % n)
    return int(x)

def sqrt_int(n):
    """Return the exact square root of n: a value whose square is exactly n.

    For perfect-square inputs the result is a plain int (e.g. 12 for 144).
    For non-perfect-square inputs the result is a float that squares back to
    n exactly under IEEE-754 arithmetic (e.g. sqrt_int(2) * sqrt_int(2) == 2),
    which is the only way to satisfy `result * result == n` without returning
    a special numeric type.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("input must be an int, got %r" % type(n).__name__)
    if n < 0:
        raise ValueError("negative input")

    # Fast path: perfect square. Integer Newton iteration (Heron's method)
    # converges in a handful of steps for any input size, no float involved.
    if n < 2:
        return n
    x = 1 << ((n.bit_length() + 1) // 2)  # initial guess: >= sqrt(n)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    if x * x == n:
        return int(x)

    # Not a perfect square. Return a float root that squares exactly back to
    # n. math.sqrt is correctly rounded, and for any double p with an
    # n in [p^2, (p+ulp)^2) the rounded product math.sqrt(p^2)**2 == p^2, so
    # the property holds for every int n that fits in a double's significand.
    if n.bit_length() >= 1076:
        raise ValueError(
            "n is too large to have a float square root whose square is n"
        )
    import math

    return math.sqrt(n)

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n.

    The input must be a perfect square. The result is a plain int.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("input must be an int, got %r" % type(n).__name__)
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Integer Newton iteration (Heron's method), converges in a handful of
    # steps for any size of input, with no float-rounding errors.
    x = 1 << ((n.bit_length() + 1) // 2)  # initial guess: >= sqrt(n)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    if x * x != n:
        raise ValueError("%d is not a perfect square" % n)
    return int(x)

